INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(348300, 0, 3483, 0, 0, 8, 'Hellfire Peninsula', 'Hellfire Peninsula is a red and broken waste, one of the fragments of Draenor that survived the day Ner''zhul tore the world apart with his portals. Long before that, the warlocks of the old Horde had already drained the land of life. At its heart stands Hellfire Citadel, once the Horde''s great stronghold, and from its gates the Path of Glory, paved with draenei bones, runs east to the Stair of Destiny and the Dark Portal. For twenty years the Sons of Lothar have held out at Honor Hold. Now the portal has woken again. The Burning Legion pours in under Doom Lord Kazzak, raising forge camps along the northern ridges, while the citadel spills out the red-skinned fel orcs of a new Fel Horde. Against them the Horde has raised Thrallmar, blood elf pilgrims rest at Falcon Watch, draenei keep the Temple of Telhamat, and the Cenarion Expedition studies a land in torment.', 'warcraft.wiki.gg/wiki/Hellfire_Peninsula (surviving part of Draenor, warlock magic withered the land, Ner''zhul''s portals, factions); npc_text 9932 (Danath: this world was ripped asunder); npc_text 9933 (Sons of Lothar remained here); quest 10047 description (Path of Glory paved with bones); quests 10123, 10142 (Kazzak commands the Legion in Outland); quest 10388 reward text (forge camps); quests 9607, 11002 (fel orcs made with Magtheridon''s blood)'),
(348301, 1, 3483, 1, 0, 8, 'The Stair of Destiny', 'On the Outland side of the Dark Portal a vast stair descends to the plain, and at its foot the armies of Azeroth hold the gate against the Legion. Alliance and Horde camp here side by side under Commander Duron and Lieutenant General Orion, with healers tending the wounded, peons and peasants hauling supplies, and quartermasters for both sides. Demons come at the stair in waves, and the defenders meet them in the field. Justinius the Harbinger calls the soldiers of Azeroth to break the demonic charge in the Light''s name, while the tauren Melgromm Highmountain rallies his hunters to show the Legion that their world is not for the taking.', 'DB spawns in area 3539: 19229, 19253, 18966, 18969, 19455 Nurse Judith, 19447 Brother Daniels, 19425 Orgrimmar Peon, 19444 Peasant Worker, Wounded Stormwind Infantry, Injured Grunt, quartermasters 19451, 19452, 19436; creature_text 18966, 18969; quests 10288, 10120 (reports carried by flight to Honor Hold and Thrallmar); quest 10119 reward text (troops of both sides fend off Legion platoons trying to take the platform); warcraft.wiki.gg/wiki/Path_of_Glory (Pit Commander returns to the Stair of Destiny)'),
(348302, 1, 3483, 2, 0, 8, 'The Path of Glory', 'The Path of Glory runs from the gates of Hellfire Citadel to the foot of the Stair of Destiny, and the orcs who named it paved it with the bones of the draenei they slaughtered. Warp-Scryer Kryv of Honor Hold mourns that his people were denied burial in the Light, and cleanses the trampled skeletons with holy water so their crying souls might rest. Along the road lie the wrecks of an older war: Alliance cannons on one side and Horde blade throwers on the other, still aimed at each other, which both sides now salvage or burn. Bonechewer scavengers pick through the battlements for war machine parts, and Shattered Hand fel orcs march the stretch nearest the citadel.', 'quest 10047 description and reward text; quest 10055, 10078 (Horde blade throwers, salvage); quest 10086, 10087 (Alliance cannons, salvage); quest 10482 description (Bonechewer scavengers gather war machine parts); quest 10450 description; DB spawns in area 3542: Shattered Hand Grunt, Captain, Warlock; Trampled Skeleton 182789; warcraft.wiki.gg/wiki/Path_of_Glory (runs from the Stair of Destiny to Hellfire Citadel, paved with draenei bones, ruined cannons and blade throwers); quest 10047 log text (Draenei Holy Water)'),
(348303, 1, 3483, 3, 0, 8, 'Honor Hold', 'Honor Hold is the last bastion of the Sons of Lothar, the survivors of the Alliance expedition who have held this keep for twenty years behind walls the fel orcs have battered and broken. Force Commander Danath Trollbane leads from the keep, and the reinforcements now arriving through the portal have given its weary defenders fresh hope. Field Commander Romus brought the newest troops from Nethergarde, the draenei Warp-Scryer Kryv reads demonic script in the war room, and the old priest Malgor Devidicus sits over his mug at the inn. The hold''s own mine has been overrun by gan''arg, to the despair of Foreman Biggums, while in the courtyard a dog named Fei Fei buries whatever he can steal.', 'npc_text 9933, 9939 (Sons of Lothar, two decades); quest 10138 description (Honor Hold''s shattered walls); quest 10046 description (Romus left Nethergarde with a large force); npc_text 8771 (Romus); quest 10395 (Kryv in the war room); quest 10058 (Devidicus in his cups); quests 10079, 10099 (gan''arg in the mine, Z''kral); quest 10916, 10919 (Fei Fei); warcraft.wiki.gg/wiki/Honor_Hold'),
(348304, 1, 3483, 4, 0, 8, 'Thrallmar', 'Thrallmar is the Horde''s foothold in Outland, raised by the warchief''s expedition and commanded by Nazgrel. It stands caught between Hellfire Citadel to the west and the Legion''s camps on the ridges behind it, and the Legion has bombarded it almost since the day it was built. Two of Thrall''s chosen serve here, Far Seer Regulkut, the Eyes of the Warchief, and Shadow Hunter Ty''jin, his Ears, while his Hand, Overlord Hun Maimfist, leads the crew at Reaver''s Fall. General Krakork barks at his grunts, Magister Bloodhawk deciphers captured Legion script, and peons patch the palisade under Watch Commander Krunk. Northwest of the walls a goblin foreman struggles to run a mine full of gan''arg and sleeping peons.', 'npc_text 9995 (Nazgrel safeguards the expedition); warcraft.wiki.gg/wiki/Thrallmar (founded and led by Nazgrel); quest 9572 description (caught between the citadel and the Legion); quest 10089 description (bombardment since its establishment); creature_template subnames 16574, 16575, 16576; creature_text 19255; quest 10393 reward text (Bloodhawk); npc_text 8717 (Krunk, peons on the walls); quests 10236, 10088 text, 10630 (Razelcraz''s mine northwest of Thrallmar); DB spawn: Hun Maimfist 16576 stands in area 3807 Reaver''s Fall; quest 10124 (Maimfist''s crew)'),
(348305, 1, 3483, 5, 0, 8, 'Hellfire Citadel', 'Hellfire Citadel was the stronghold of the old Horde, the staging ground from which its armies marched against the draenei. The Alliance tore down its walls twenty years ago, yet now it is the heart of a new Fel Horde. Each day its gates open and more red-skinned fel orcs pour out, and how so many have come to be is a secret the fortress still keeps. Kargath Bladefist rules them as their self-styled warchief. Outside the gates the Shattered Hand drill for war: Force-Commander Gorax trains captains at the citadel''s foot and Drillmaster Zurok marshals the troops where the Path of Glory ends. Behind the fortress lies Hellfire Basin, where a way leads down into the citadel''s deepest vaults.', 'npc_text 9941 (Danath: tore down the walls of their Hellfire Citadel); quest 9492, 9495 (Kargath, self-styled Warchief); quest 10876, 10937 descriptions (Gorax, Zurok); DB spawns: Gorax 19264 and Zurok 19312 in area 3545; meeting stone and raid portal in area 3955; quest 10838 (Hellfire Basin behind the citadel); warcraft.wiki.gg/wiki/Hellfire_Citadel (staging ground of the Horde''s conquest of Draenor); quest 11002 description (Illidan''s fel orc army; source only); quest 9607, 9608 reward text (Danath and Nazgrel do not know of the pit lord until the Blood Furnace is explored; not told here); quest 10122 description (each day the gates open and more fel orcs pour out; source only); quests 9587, 9588 reward text (Dark Tidings: the letter signed by Illidan is a Hellfire Ramparts revelation; not told here)'),
(348306, 1, 3483, 6, 0, 8, 'The Ramparts and Gor''gaz Outpost', 'South and north of Hellfire Citadel, broken lengths of the old outer walls stretch across the plain, and the fel orcs have turned them into a chain of camps. The Shattered Hand hold both the Northern and Southern Ramparts, where guards, berserkers and acolytes keep watch and the brute Mekthorg the Wild sometimes prowls. Warboss Nekrogg commands on the southern wall. At Gor''gaz Outpost, below the ramparts, a captured human soldier and an orc scout wait in cages, and it was near here that Colonel Jules of Honor Hold was stricken by a demonic curse. Goblin peons dragged off from Thrallmar''s mine have been found caged in the northern camps.', 'DB spawns: area 3809 Shattered Hand Guard x42, Mekthorg 18677, Warboss Nekrogg 19263; area 3810 Manni 19763 and Moh 19764 with cages; area 3811 Private Imarion 19266, Scout Makha 19265, Fel Orc Cages; quest 10122 text (camps along the ramparts south of the fortress); quest 10903, 10909 (Jules cursed near Gor''gaz Outpost); quest 10238 (peons taken to the fel orc camps along the wall)'),
(348307, 1, 3483, 7, 0, 8, 'Expedition Armory', 'South of Honor Hold lie the ruins of the Expedition Armory, a Sons of Lothar base that fell near the end of the Alliance invasion of Draenor. Orcs and Horde death knights stormed it, and the death knights laid a curse on its defenders that trapped their souls between life and death. They are the Unyielding: footmen, knights and sorcerers who still fight the battle they lost, led by the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos, while Commander Hogarth keeps to the eastern tower. Ghostly townsfolk drift through the ruined buildings. Few in Honor Hold will speak of the place, and Father Devidicus once kept his quarters close by.', 'quest 10050 description and request text; quest 10057; quest 10230 description (destroyed by orcs and death knights); quest 10258 (Hogarth in the eastern tower); quest 10058 (quarters to the south of the armory); DB spawns in area 3546: Unyielding Footman/Knight/Sorcerer, Ghostly Denizen 16976, Thalvos 16978, Xintor 16977, Hogarth 19937; warcraft.wiki.gg/wiki/Expedition_Armory (ruined Sons of Lothar base, Nightwatch Inn ruins)'),
(348308, 1, 3483, 8, 0, 8, 'Zeth''Gor', 'Zeth''Gor is a ruined orc fortress in the southeastern hills, now the lair of the Bleeding Hollow clan, fel orcs who struck a pact with demons. Warlord Morkh commands from its barracks, and his cruel tactics have cost Honor Hold dearly. Worg Master Kruush leads riders who prey on the supply trains to Spinebreaker Post, and in a cave beneath the fort lives the witch Grillok Darkeye, who traded one of his own eyes to dark powers. The orcs carry talismans made from the insignias of fallen Honor Hold soldiers, and their witches lay curses on the clan''s own blood.', 'quest 10485 (Morkh in the barracks, his tactics); quest 10809 (Kruush, supply trains); quest 10834 description (Grillok''s lost eye); quest 10059 description (lair a cave beneath the outpost); quest 10483, 10484 (cursed talismans); quest 10538 (cursed cauldron); quest 10895 (four guard towers); quest 10792 (burning Zeth''Gor); npc_text 10610 (clan made a pact with demons); DB spawns in area 3582: 16964, 19442, 19457, Cursed Cauldron 184715; quest 10538 (witches'' curses on the blood)'),
(348309, 1, 3483, 9, 0, 8, 'Spinebreaker Post', 'Spinebreaker Post is a small Horde camp in the southern hills, close enough to Zeth''Gor that its captain boasts she can smell the Bleeding Hollow''s blood. Stone Guard Ambelan keeps watch and warns visitors to keep their voices low. The post draws an unusual crowd. The Forsaken Althen the Historian and Emissary Mordiba study the Unyielding ghosts of the Expedition Armory, hoping to win them as allies. Apothecary Albreck of the Royal Apothecary Society tests the blood of fel orcs, Zezzak tries to see into the mind of the witch Grillok, and Ogath the Mad pursues the secrets of the void. Even the young scholar Grelag ended up here, limping on a wounded leg.', 'npc_text 10610 (Captain Darkhowl); npc_text 9777 (Ambelan); quests 10220, 10229, 10230 (Mordiba, Althen, Forsaken); quest 10835 (Royal Apothecary Society); quest 10813 (Zezzak); quests 10278, 10295 (Ogath); quest 9345 description (Ambelan brought Grelag here); DB spawns in area 3812: 22107, 19332, 19736, 19682, 21279, 22231, 19683, 16858; quest 9344 (Grelag a promising student of history); CreatureDisplayInfo 19791, 19790 (Forsaken), 18486 (female orc)'),
(348310, 1, 3483, 10, 0, 8, 'The Zeppelin Crash', 'In the southern wastes beyond the Expedition Armory lies the wreck of a goblin zeppelin out of Area 52, bound for Terokkar Forest by a shortcut that went badly wrong. The Legion shot it down despite its flag of truce. Its pilot, Screaming Screed Luckheed, swears he will never take another shortcut, and is busy rebuilding the engine to run on voidwalker essence from the Warp Fields. His companion, the cook Legassi, has turned the crash site into a kitchen of ravager eggs, helboar bacon and buzzard wings. Screed''s cousin, Foreman Razelcraz, came to Outland on his promise of a fortune and now runs a miserable mine near Thrallmar, hoping the zeppelin crashes.', 'npc_text 9781 (Legassi: from Area 52, shortcut to Terokkar); npc_text 9789 (Screed); quest 10213 description and reward text (crash beyond the Expedition Armory, flag of truce); quest 9351; quests 9349, 9356, 9361 (Legassi''s meal); quests 10236, 10238 (Razelcraz, cousin); DB spawns: 19344, 19367 in area 3816'),
(348311, 1, 3483, 11, 0, 8, 'The Warp Fields and Void Ridge', 'At the southern edge of the peninsula the ground breaks away into the abyss, and there the walls between worlds grow thin. In the Warp Fields rogue and uncontrolled voidwalkers wander loose, and everyone seems to want them. Blood elf pilgrims feed on their essence, the draenei of Telhamat sever them from this world with charged crystals to keep that power from the elves, and a stranded goblin pilot wants them for engine fuel. Farther east, through a pass beyond Zeth''Gor, lies Void Ridge, where voidcallers and collapsing voidwalkers haunt the brink. It is on that brink that Ogath the Mad of Spinebreaker Post means to push his warp rift experiments furthest.', 'quest 10278 description (edge of the abyss where time and space are weak); quest 9383 (Elsaana: blood elves consume voidwalker energies); quest 9351; quest 10294 description (Void Ridge east beyond Zeth''Gor through a pass); quest 10295; DB spawns: Rogue/Uncontrolled Voidwalker in 3796; Collapsing Voidwalker, Vacillating Voidcaller in 3802'),
(348312, 1, 3483, 12, 0, 8, 'The Legion Front', 'East of Thrallmar and Honor Hold the Burning Legion holds a long front across the plain, a mobile command post guarded by wrathguards, fel handlers and their netherhounds, with shivan subjugators overseeing all. Along it stand portals that draw in reinforcements from across Outland, and great gateways rise on either side of the Path of Glory. Antennas jut from the ground to carry the Legion''s commands to its forge camps. Facing it stand two forward bases: the Horde''s Reaver''s Fall, raised on an old farm beside the wreck of a fel reaver, and the Alliance''s Expedition Point, built where a Legion base once stood. Their soldiers are radicals, sworn to wipe out the Legion entirely.', 'quest 10125 description (mobile command station, antennas); quest 10127 description (handlers, wrathguards, shivan subjugator); quests 10208, 10144 (portals Xilus, Kruul, Grimh, Kaalez); quests 10129, 10146 (Gateways Murketh and Shaadraz on either side of the road); quests 10124, 10143 (Reaver''s Fall, Expedition Point, radicals); DB spawns in area 3804: Wrathguard, Fel Handler, Netherhound, Subjugator Shi''aziv, Yalqiz, Legion Antennas, Portal gameobjects; warcraft.wiki.gg/wiki/Fel_Reaver (Reaver''s Fall)'),
(348313, 1, 3483, 13, 0, 8, 'The Forge Camps', 'Along the northern ridges above Thrallmar the Legion''s engineers have raised a line of forge camps, where mo''arg overseers drive gan''arg servants day and night to build fel reavers. Forge Camp: Mageddon in the east is still under construction. Forge Camp: Rage has fel cannons aimed straight at Thrallmar, and at Invasion Point: Annihilator a warp portal draws fresh demons into Outland under Warbringer Arix''Amal. Behind the camps rises the Abyssal Shelf, the Legion''s main production grounds, where gan''arg peons, mo''arg overseers and fel cannons crowd a high plateau. Gryphon and wyvern riders bomb it without rest, fearing what would march out if they let up.', 'quest 10388 reward text (forge camps build fel reavers); quest 10390 (Mageddon not complete); quest 10391 (fel cannons aimed at Thrallmar); quest 10392 (warp portal, Arix''Amal); quest 10162 description (main production area behind the forge camps); quest 10347 description (fear of a large demon attack from the north); DB spawns: Gan''arg Servant, Mo''arg Forgefiend, Fel Cannon MKI in 3541/3548/3549; Gan''arg Peon, Mo''arg Overseer, Fel Cannon in 3803; Arix''Amal 19298 in 3549'),
(348314, 1, 3483, 14, 0, 8, 'Throne of Kil''jaeden', 'The Throne of Kil''jaeden is a great mountain on the northern edge of the peninsula, and the orcs'' histories tie it to the warlock Gul''dan and the demon lord whose name it bears. Today it is the seat of Doom Lord Kazzak, master of the Legion''s armies in Outland, who waits on its heights for any who dare to climb. Fel sparks drift across its slopes, and the Legion holds the mountain as its own.', 'warcraft.wiki.gg/wiki/Throne_of_Kil''jaeden (named by Gul''dan, Kazzak, Kael''s forces led from here to Quel''Danas); quests 10123, 10142 (Kazzak commands the Legion in Outland); npc_text 12239 (Seyla: gateway Kael''s armies used to retreat to the Sunwell); quests 11515, 11516 descriptions; DB spawns in area 3547: Kazzak 18728, Felblood Initiate, Suspended Terrorguard, Wrath Herald, Seyla 24937; warcraft.wiki.gg/wiki/Throne_of_Kil''jaeden (felblood elves siphon suspended terrorguards); DB spawns in area 3547: Wrath Herald 24919, Incandescent Fel Spark 22323, Suspended Terrorguard 24933'),
(348315, 1, 3483, 15, 0, 8, 'Pools of Aggonar', 'North of Hellfire Citadel lie the Pools of Aggonar, once sacred springs of the draenei. When the blood of the demon Aggonar was spilled into them it fouled the holy waters, and from them spawned slimes and blistering rots, while terrorfiends feed on the old demonic power. Aggonar''s bones still lie at the northern end of the pools. The draenei of Telhamat strive to cleanse the pools, but the blood elves of Falcon Watch harvest the felblood for its power and ambush the anchorites sent to purify it. The Legionlord Arazzius the Cruel has gathered his terrorfiends here too, and a blood elf scholar who came to study the slimes vanished in the pools.', 'quest 9426 description; quest 9427 description and reward text (bones at the northern end, Aggonis); quest 9366 description; quest 9370 description; quest 10399 description (Arazzius''s terrorfiends near the pools); quest 10136 description; quest 9374 description (Arelion went missing in the pools); DB spawns in area 3553: Blistering Oozeling, Blistering Rot, Terrorfiend, Arazzius 19191'),
(348316, 1, 3483, 16, 0, 8, 'Temple of Telhamat', 'On the western frontier of the peninsula stands the Temple of Telhamat, one of the few draenei holy places to survive. When Prophet Velen prepared for the journey that took him to Azeroth, some draenei chose to stay and re-establish their people at the sacred sites, and here they are led by the blind elder Amaan the Wise. They call themselves the Omenai. The temple also shelters Broken who have escaped the Illidari: Ikan, who teaches the freed Dreghood the old ways of the Light, and the half-mad Makuru, who owes his life to a young paladin named Sedai. From here the anchorites work to cleanse the Pools of Aggonar.', 'quest 10093 description and reward text (draenei who remained behind reestablished a presence at holy places); npc_text 8792 (Amaan''s lost sight); npc_text 8852 (the Omenai); quest 9399 (Ikan, Omenai, Dreghood); npc_text 8854; quest 9424 (Makuru, Sedai); quest 9426; warcraft.wiki.gg/wiki/Temple_of_Telhamat (Omenai led by Amaan); DB spawns in area 3552: 16796, 16799, 16833, Escaped Dreghood 16836'),
(348317, 1, 3483, 17, 0, 8, 'Falcon Watch', 'Falcon Watch is the newly built outpost of the blood elves in the southwest of the peninsula, beyond Hellfire Citadel, and a resting place for the pilgrims who cross Outland in search of Prince Kael''thas. Many arrive exhausted and starved for magic. Ranger Captain Venn''ren seeks safe routes for them, for Alliance scouts watch every road. His people are ambitious: Ryathen the Somber harvests demonic felblood, Arcanist Calesthris covets the magic of the arakkoa, and an apothecary of the Forsaken tests demonic essences on a captive draenei. Not every trouble is the Legion''s. The magistrix Carinda mourns her husband Arelion, a scholar who went into the Pools of Aggonar to study slimes and never came back.', 'quest 9498, 9499 descriptions (recently built, southwest beyond the citadel); npc_text 8659 (Venn''ren: reach Kael''thas, safe routes); quest 9377 description (pilgrims exhausted, need magic); quest 9391 reward text (Alliance watching all the roads); quest 9366; npc_text 8680 and quest 9396 (Calesthris); quest 9387 (Azethen''s draenei subject); creature_template 16794 faction 68 (Undercity); quests 9374, 10286, 10287, 9472'),
(348318, 1, 3483, 18, 0, 8, 'Mag''har Post', 'In the hills northwest of Hellfire Citadel, hidden from the fel orcs who would destroy it, lies Mag''har Post, a camp of brown-skinned orcs who never drank the demon''s blood. These are the Mag''har, the uncorrupted, and their captain Gorkan Bloodfist trusts no stranger this close to the citadel. Their first orders are to keep the camp''s location secret, so even their shaman, Earthcaller Ryga, dares not go out to gather herbs. Many of their grunts lie sick on the Mag''har Grounds below the camp after drinking foul water. The draenei of Telhamat remember these orcs as enemies.', 'quest 9410 reward text (rarely trust strangers this close to the Citadel); quest 9406 description (free from demonic taint); quest 9442 description (keep location secret, contaminated water); quest 9447 (Debilitated Mag''har Grunts); quest 9390, 9423, 9543; DB spawns: 16845, 17123 in 3555; Debilitated Mag''har Grunt 16847 in 3801; warcraft.wiki.gg/wiki/Mag''har'),
(348319, 1, 3483, 19, 0, 8, 'The Great Fissure', 'The Great Fissure is a long scar in the earth east of Falcon Watch, crawling with stonescythe rock flayers and the tunnelers they hunt with. The Broken who flock to the Dark Portal from the south must cross it, and the flayers see them as easy prey. Blacktalon the Savage, the vicious matriarch of the flayers, dwells in a cave within and has killed many hunters. Ranger Captain Venn''ren means to mark a secret path through the fissure with three beacons, so that blood elf pilgrims can avoid the roads the Alliance watches. Another cave here is the only place in the peninsula where the rare drycap mushroom grows, an ingredient for healing salves.', 'quest 9340 description (secret path, rock flayers); quest 9391 (three beacons); quest 9398 description (Broken flocking to the portal, flayers prey on them); quests 9466, 9490 (Blacktalon in a cave, took many hunters'' lives); quest 9442 (drycap cave); DB spawns in 3543: Stonescythe Whelp/Alpha, Tunneler, Fulgorge rare, three beacon gameobjects'),
(348320, 1, 3483, 20, 0, 8, 'Den of Haal''esh', 'In the southwest the arakkoa of the Haal''eshi make their den among the cliffs of Haal''eshi Gorge. Smart as any gnome by one dwarf''s reckoning, they wield lightning magic and a violent temper, and they raid Alliance patrols and supply caravans. They have tamed the kaliri birds and keep their nests here. Their mage Avruu works his magic among them. The dwarf brothers Gremni and Mirren Longbeard, hired by Honor Hold to deal with the bird-men, camp nearby with more ale than ammunition.', 'quest 9417 description (smart as any gnome, lightning, attacking patrols); quest 9558 (raiding supply caravans, Longbeards packed more ale); quest 9397, 9420 (kaliri); quest 9418 (Avruu, Aeranas, altar southeast); npc_text 8672, 8673; DB spawns: Haal''eshi Talonguard/Windwalker, Kaliri Nests, Avruu 17084 in 3556; Haal''eshi Altar 181606 in 3798'),
(348321, 1, 3483, 21, 0, 8, 'Ruins of Sha''naar', 'The Ruins of Sha''naar are an old draenei settlement in the west of the peninsula, now a slave camp. Illidari taskmasters drive the Dreghood, a tribe of Broken, to dig through the ruins for a powerful crystal of the ancient draenei, one their own captives doubt is even there. Their overseer is Arzeth the Merciless, servant of the Betrayer, who demands that the wretches be worked to the bone. The tribe''s elders have been chained in the depths, and with them the spirits of wind, fire and water left their people. Some Dreghood have escaped to the Temple of Telhamat, and the scholars of Falcon Watch come to collect demonic essence from the taskmasters.', 'npc_text 9787 (Naladu: searching for a powerful crystal, likely not here); creature_text 19354 (Arzeth: Ata''mal crystal, work them to the bones); creature_template 19354 subname Servant of the Betrayer; quest 10368 (elders imprisoned, spirits); quest 9399 (Ikan, Dreghood); quest 9387 (taskmasters); DB spawns in 3551: Dreghood Brute, Geomancer, Illidari Taskmaster, Arzeth, Naladu, elders'),
(348322, 1, 3483, 22, 0, 8, 'Cenarion Post', 'On the road west toward Zangarmarsh, before it climbs over Thornfang Hill, the Cenarion Expedition keeps a small camp. Its druids are here to study what has happened to this tortured land and to undo what harm they can. The tauren Thiah Redmane collects blood from the ever-mutating helboars, hoping it holds the base of an antidote. Mahuram Stouthoof keeps the pass through Thornfang Hill clear of ravagers so the way to the Cenarion Refuge stays open. Earthbinder Galandria Nightbreeze and the blunt Tola''thion investigate a great red crystal that fell from the sky onto the ridge to the north. The post welcomes help from Falcon Watch and Telhamat alike.', 'quests 10442, 10443 (south side of the road to Zangarmarsh, Thornfang Hill); quest 10443 description (here to study and reverse damage); npc_text 8716; quests 9372, 10255 (Thiah); quest 10159 (Mahuram); quests 10132, 10349 (crystal, Galandria, Tola''thion); npc_text 9770 (Tola''thion); DB spawns in area 3808: 16885, 16888, 16991, 19293, 19294'),
(348323, 1, 3483, 23, 0, 8, 'Fallen Sky Ridge', 'Fallen Sky Ridge rises north of the Cenarion Post, and at its center a huge red crystal juts from the ground. It fell from the sky not long ago, shaking the land with a mighty earthquake, and soon after the ridge filled with raging colossi, mountain giants that had never been seen here before. The druids of the Cenarion Expedition sense a sickly evil flowing from the crystal. It is too large to move and beyond their power to destroy, and Earthbinder Galandria Nightbreeze is eager to find what links it to the giants.', 'quest 10132 description; quest 10134 reward text (sickly evil aura); quest 10351 description (too big to move, circle at the northwest corner); quest 10351 reward text; DB spawns in area 3797: Raging Colossus x28'),
(348324, 2, 3483, 1, 1, 8, 'Force Commander Danath Trollbane', 'Danath Trollbane, nephew of King Thoras of Stromgarde, followed Khadgar and Turalyon through the Dark Portal two decades ago to finish the Horde for good. In the war''s final hours Draenor was torn apart, and his dear friends, he says, were lost to the void. Danath took command of those left behind, the Sons of Lothar, and has held Honor Hold ever since, praying for the day the portal would open. Now it has, and Field Commander Romus has brought grim news: Lordaeron is lost, and his own Stromgarde has met no kinder fate. Danath swears that if he ever returns to Azeroth, Stromgarde will rise again. Until then he has orcs to fight, as he has all his life.', 'npc_text 9932, 9933, 9941, 8772 (Danath''s gossip); quest 10254 reward text (leader of the Sons of Lothar); warcraft.wiki.gg/wiki/Danath_Trollbane (nephew of Thoras Trollbane, Alliance Expedition, took command of the Sons of Lothar)'),
(348325, 2, 3483, 2, 2, 8, 'Nazgrel', 'Nazgrel was among the orcs Thrall freed from the internment camps, and he became the warchief''s chief of security in Durotar. Now, behind a ragged wolf mask, he commands Thrallmar as Thrall''s right hand, charged with safeguarding the expedition to the world the orcs came from. He calls Thrall his warchief and his blood-brother, and would follow him through the gates of the abyss. He knows the risk: resources, warriors and the defense of Durotar itself have been staked on this venture. Thrall hopes to find the true tale of the orcish people somewhere in the wreckage of Draenor, and in his darkest moments Nazgrel fears that tale is better left untold.', 'npc_text 9995, 10003, 10004 (Nazgrel''s gossip); quest 10291 reward text (ragged wolf-mask); quest 9405 description; warcraft.wiki.gg/wiki/Nazgrel (freed from an internment camp by Thrall, in charge of Durotar''s security, commands Thrallmar)'),
(348326, 2, 3483, 3, 0, 8, 'Doom Lord Kazzak', 'After the Legion''s defeat at Mount Hyjal, Lord Kazzak gathered its remnants in the Blasted Lands, and when the Dark Portal opened once more he passed through into Outland. Now he is Doom Lord Kazzak, commander of the Burning Legion''s war in this shattered land, and his lieutenants direct demon troops across Hellfire Peninsula in his name. He waits atop the Throne of Kil''jaeden, still nursing the sting of the Third War, and promises that the shadow of the Legion now falls over this world and that all of mortal creation will be undone. His herald, Vorakem Doomspeaker, stalks the Legion''s camps below. Where one demon falls, Kazzak boasts, ten shall rise.', 'creature_text 18728; quests 10123, 10142 descriptions (Kazzak commands the Burning Legion in Outland); creature_template 18679 subname Herald of Doom Lord Kazzak; DB spawns: Vorakem 18679 in areas 3541, 3553, 3804; warcraft.wiki.gg/wiki/Doom_Lord_Kazzak; data/lore/blasted_lands.json 409 (Kazzak at the Tainted Scar)'),
(348327, 2, 3483, 4, 0, 8, 'Arazzius the Cruel', 'Arazzius the Cruel is a Legionlord of the Burning Legion, and he holds the Pools of Aggonar as his own doorstep, with a host of hellish terrorfiends gathered around him. He meets those who reach him with fury and scorn, crying out at the insolence of anyone who thinks to defeat him there, calling each a child playing in a world beyond their comprehension, and warning that their weapons are nothing to him.', 'quest 10136 description (one of Kazzak''s lieutenants, commands the Legion ground forces); quest 10399 description (secret Legionlord, terrorfiends); quest 10400 description; creature_text 19191; creature_text 19255 (the warchief''s price on Arazzius''s head); DB spawn: 19191 in area 3553; creature_text 19191 groups 0, 2, 3'),
(348328, 2, 3483, 5, 1, 8, 'Amaan the Wise', 'Amaan the Wise is the elder of the Omenai, the draenei who chose to stay in Outland when Prophet Velen left and to keep their people''s holy places alive. He lost his sight many years ago, but insists he never needed it to see what truly matters. From the Temple of Telhamat he sends helpers to cleanse the Pools of Aggonar, once his people''s sacred springs, and any friend of Warp-Scryer Kryv is a friend of his.', 'npc_text 8792; quest 10093 description and reward text; quests 9426, 9427; quest 9430, 9545 (counsel after Sedai); warcraft.wiki.gg/wiki/Temple_of_Telhamat (Omenai led by Amaan); quest 10093 reward text (a friend of Kryv is a friend of his)'),
(348329, 2, 3483, 6, 2, 8, 'Gorkan Bloodfist', 'Gorkan Bloodfist is the captain of the Mag''har at their hidden post northwest of Hellfire Citadel. Wary of every stranger, he keeps his orcs out of sight of the fel orcs, and spares an unannounced visitor only because Earthcaller Ryga senses that the spirits walk with them. Even then he warns that his people rarely trust strangers this close to the citadel, and that a visitor is welcome among them, at least for the time being.', 'npc_text 8813; quest 9410 reward text; quest 9406 description; creature_template 16845 subname Mag''har Captain; quest 9441 reward text'),
(348330, 2, 3483, 7, 1, 8, 'Father Malgor Devidicus', 'Father Malgor Devidicus is an old priest of the Sons of Lothar, usually found deep in his cups. On the eve of the expedition''s departure for Draenor he gave his book, Mysteries of the Light, to Turalyon, and through the whole campaign and the long years after, Turalyon never failed to read the day''s passage to his men. When Turalyon left them again, he gave the book back. Malgor kept it in his quarters to the south of the Expedition Armory, believing it safe there, and calls himself a fool for it.', 'quest 10058 description, request and reward text; creature_template 16825 faction 1667'),
(348331, 2, 3483, 8, 0, 8, 'The Fel Reaver', 'The fel reaver is the Legion''s great war engine, a towering construct on long striding legs that trails green smoke wherever it goes. Mo''arg engineers and their gan''arg servants build them in the forge camps on the northern ridges, and the Horde and Alliance fight hard to stop that work before a fleet of them is loosed. A few already roam Hellfire Peninsula, crushing careless travelers who stray into their path. At their heart burns a scalding core of fel fire, far hotter than any forge.', 'warcraft.wiki.gg/wiki/Fel_Reaver (demonic machines, long legs, green smoke, mo''arg and gan''arg, forge camps); quest 10764 description (core of fel fire hotter than normal fire); quest 10758 description; quest 10092 description (fleet of fel reavers); DB spawns: Fel Reaver 18733 x2 in Hellfire (area 3799 and the open zone)'),
(348332, 2, 3483, 9, 2, 8, 'Ogath the Mad', 'Ogath the Mad has wandered Outland for a lifetime, searching for the truth of the void. Grown old and weak, he now waits at Spinebreaker Post with an unstable warp rift generator of his own design, which he means to set off in the Warp Fields, where time and space wear thin at the edge of the abyss. He hopes to learn the secrets of the voidwalkers from whatever comes through, and dreams of one day opening a portal to the beyond that cannot be closed.', 'quest 10278 description and reward text; quest 10294; quest 10295 description and reward text; DB spawn 19683 in area 3812'),
(348333, 3, 3483, 1, 0, 8, 'The Legion Front', 'Fresh soldiers from Azeroth are soon sent to the supply caravans outside the walls of Thrallmar and Honor Hold, where Sergeant Shatterskull and Sergeant Altumus watch the Legion. Altumus asked Danath for a full battalion, and is not shy about saying so. Kazzak himself is beyond reach, but his dreadlords call down the infernal storms that rain on both outposts from Felspark Ravine and the Path of Anguish, and they can be killed. Beyond them, along the Legion Front, portals and great gateways draw in demon reinforcements from across Outland.', 'quests 10121, 10123, 10124, 10208, 10129, 10162 (Horde chain); quests 10141, 10142, 10143, 10144, 10146, 10340, 10344, 10163 (Alliance chain); quest 10141 reward text (asked for a full sized battalion); quest 10340 reward text, 10344 reward text (Shatter Point); quest 10121 reward text (Hyjal some five years past)'),
(348334, 3, 3483, 2, 0, 8, 'The Forge Camps', 'Scouts soon learn that the Legion camps on the ridge behind Thrallmar are forge camps, where the demons build their fel reavers. Nazgrel sends his best to kill the gan''arg and their master Razorsaw at unfinished Mageddon, to blow up the fel cannons of Forge Camp: Rage, and to slay Warbringer Arix''Amal at Invasion Point: Annihilator and overload its warp portal with his key. From Honor Point, Field Marshal Brock sends the Alliance against the same camps, grudging but clear that Thrallmar must not fall, since the Alliance needs the Horde to help hold the line at the Dark Portal.', 'quests 10388, 10390, 10391, 10392, 10393, 10389, 10136 (Horde chain); quests 10382, 10394, 10396, 10397, 10395, 10399, 10400 (Alliance chain); quest 10396 description (need the Horde to hold the line); item 29590 Burning Legion Missive (drops from Razorsaw) starts 10393; item 29588 (drops from Arix''Amal) starts 10395'),
(348335, 3, 3483, 3, 0, 8, 'Know Your Enemy', 'Rumors reach Honor Hold of a new breed of orc, larger, meaner and more cunning than any the Sons have known, and Danath sends recruits to Lieutenant Amadi at the broken tower west of the hold. In Thrallmar, Vurtok Axebreaker rages at the sight of the red-skinned Bonechewers, depraved cousins of his own people, and wants their blood gathered so the apothecaries can learn how they fell to the demon taint the orcs of the Horde so recently threw off. Both sides begin with the Bonechewer scavengers on the ruined battlements of the Path of Glory, and both soon turn to the Bleeding Hollow of Zeth''Gor.', 'quests 10160, 10482, 10483, 10484, 10485 (Alliance chain); quests 10450, 10449, 10242, 10538, 10835, 10864, 10838, 10875, 10876 (Horde chain); quest 10450 description; quest 10835 reward text'),
(348336, 3, 3483, 4, 1, 8, 'The Exorcism of Colonel Jules', 'While the fight against Zeth''Gor goes on, Corporal Ironridge receives word that his commanding officer, Colonel Jules, was stricken by a demonic corruption in battle near Gor''gaz Outpost and is growing worse. In an upper room of the Honor Hold inn, the draenei Anchorite Barada prays over him while his assistant Klatu prepares for an exorcism. Jules''s tormented spirit seeks peace through vengeance, so an anchorite relic is to be set down at Gor''gaz to draw out the fel spirits of the Shattered Hand for destruction. Klatu''s prayer beads, needed for the rite, have gone missing in the courtyard, and he suspects Fei Fei, the hound of Warrant Officer Proudwell.', 'quests 10903, 10909, 10916, 10919, 10935, 10936, 10937 (descriptions and reward texts); creature_text 22431, 22432; npc_text 10706'),
(348337, 3, 3483, 5, 2, 8, 'The Mag''har', 'Hellfire Citadel has learned that Thrallmar is sending an envoy to Falcon Watch, and has set an ambush. Nazgrel''s scouts name the assassin, Krun Spinebreaker, who waits along the road north of the citadel, and Nazgrel sends an agent to slay him and show the fel orcs that the Horde is not to be trifled with. Nazgrel never forgets why the warchief backed this expedition: for the blood elves Outland is a promised land, but for the orcs it is a return home, to the world where their roots lie.', 'quests 9400, 9401, 9405, 9410, 9406, 9438, 9441, 9442, 9447 (descriptions and reward texts)'),
(348338, 3, 3483, 6, 1, 8, 'The Death of Sedai', 'At the Temple of Telhamat, Anchorite Obadei fears for his brother Sedai, an idealist who set out for the orcs of Mag''har Post, sure the time was ripe to set old differences aside and make peace. He has been missing for days, and Obadei asks a newcomer to search to the east, where Sedai must be somewhere near. The draenei have reason for dread: the orcs once drove them near to extinction, and since then they have kept away from orcs even when no demon drove them.', 'quests 9390, 9423, 9424, 9543, 9430, 9545 (descriptions and reward texts)'),
(348339, 3, 3483, 7, 0, 8, 'The Unyielding', 'The ghosts of the Expedition Armory draw both sides. In Honor Hold, Honor Guard Wesilow cannot bear to raise his blade against his old comrades, cursed by Horde death knights near the end of the old invasion and trapped between life and death, so he asks newcomers to put the cursed footmen, knights and sorcerers to rest. The Horde has other plans. At Spinebreaker Post the Forsaken emissary Mordiba wants an army of undying warriors and means to beat the Unyielding into listening, and a tome carried by one of the ghosts, written in a secret Alliance cipher, is bound for Althen the Historian.', 'quests 10050, 10057 (Alliance); quests 10220, 10229, 10230, 10250, 10258 (Horde, descriptions and reward texts); item 28552 A Mysterious Tome starts 10229'),
(348340, 3, 3483, 8, 0, 8, 'The Crimson Crystal', 'Not long ago a huge red crystal fell from the sky onto the ridge north of the Cenarion Post, and an earthquake shook the land. Soon raging colossi were wandering the ridge where none had been before. The plain-spoken Tola''thion admits something is strange about the crystal''s energies, but has no time for it: in his view the cure is simply to kill enough of the giants. Some who do so notice that a fallen colossus was clutching a red shard that looks like a piece of the crystal itself.', 'quests 10132, 10134, 10349, 10351 (descriptions and reward texts); npc_text 9770; item 29476 Crimson Crystal Shard starts 10134'),
(348341, 3, 3483, 9, 0, 8, 'The Dreghood Elders', 'Chained in the depths of the Ruins of Sha''naar, the elders of the Dreghood Broken have lost their bond with the spirits of wind, fire and water, and without them their people have lost heart. Above them the Illidari taskmasters of Arzeth the Merciless drive the tribe to dig for an ancient draenei crystal. One elder, chained and powerless like the others, begs a stranger to search the huts upstairs for Naladu, the fourth elder, whom he fears is dead, for it would be a great boon to the tribe if all its elders lived.', 'quests 10403, 10367, 10368, 10369 (descriptions and reward texts); creature_text 20677, 20678, 20679; npc_text 9787');
INSERT INTO `mod_lore_codex_part` (`Entry`, `Part`, `MinState`, `MaxState`, `Body`, `Sources`) VALUES
(348308, 1, 0, 255, 'Neither side has left Zeth''Gor untouched. Guided by smoke beacons set beneath its four guard towers, the gryphon riders of Expedition Point have bombed them from the air, and Horde raiders from Spinebreaker Post have hurled burning torches into its hovels, its stable and its barracks, until the smoke and flames could be seen from the outposts.', 'quest 10895 description and reward text (four guard towers, smoke beacons, gryphon riders); quest 10792 description and reward text (torches thrown at hovels, stable and barracks)'),
(348314, 1, 12, 255, 'Wrath heralds walk the mountain''s slopes, and terrorguards hang suspended in the air while blood elves changed by demon blood drain their power. A gateway on the mountain once carried Prince Kael''thas''s armies away to the Sunwell, and the Shattered Sun keeps watch on it still.', 'npc_text 12239 (Seyla: gateway Kael''s armies used to retreat to the Sunwell); DB spawns in area 3547: Felblood Initiate 24918, Suspended Terrorguard 24933, Wrath Herald 24919, Seyla 24937 (patch 2.4); warcraft.wiki.gg/wiki/Throne_of_Kil''jaeden (felblood elves siphon suspended terrorguards; Kael''s forces led from here to Quel''Danas)'),
(348314, 2, 12, 255, 'Blasting the gateway buys only time. It is the road by which Legion reinforcements reach the Isle of Quel''Danas, and though Magistrix Seyla''s living flares can tear it apart, the demons can repair it in due time, so it must be blown up again and again.', 'quest 11516 description and reward text (stop Legion reinforcements to Quel''Danas; the demons might repair the gateway, blow it up again)'),
(348315, 1, 0, 255, 'Aggonar''s essence had not quite left this world. When a cleansing vial was poured over his bones, it rose again in the form of his foul offspring, Aggonis, and only with that demon slain could the draenei of Telhamat begin the work of restoring the pools to their old purity.', 'quest 9427 description and reward text (essence not quite gone, Aggonis, restoring the pools)'),
(348317, 1, 0, 255, 'Arelion''s journal, found in the pools, held no research at all. Its pages told of his escapades with a young blood elf woman, and Carinda, who had believed every word about fel-infused slime, set out to learn who she was.', 'quest 9374 reward text; quest 10286 description (escapades with a young female blood elf; identity not in the journal)'),
(348317, 2, 0, 255, 'His friend and confidant Magister Aledis, found on the road toward Zangarmarsh, gave up the name rather than take a beating for him: Viera Sunwhisper, a pilgrim of Falcon Watch itself. Carinda swore to show the girl that a magistrix is not one to be trifled with.', 'quest 10286 description (Aledis, road to Zangarmarsh); quest 10287 description and reward text (Viera Sunwhisper); DB spawn: Viera Sunwhisper 17226 at Falcon Watch'),
(348318, 1, 0, 255, 'Not far east of the Temple of Telhamat, on the way toward the post, lies the body of Sedai, a young draenei paladin who set out to seek peace with these orcs. He died from a blow to the back.', 'quest 9390 description and reward text; DB spawn: Sedai''s Corpse 16852'),
(348320, 1, 0, 255, 'Avruu kept a prisoner. Taken from the mage, his orb speaks with the voice of Aeranas, a spirit who once ruled the eastern winds and was bound inside it at an altar hidden southeast of the den. Carried back to that altar, the orb sets him free, and he pays for his liberty with treasure.', 'quest 9418 description and reward text (item-started from Avruu''s Orb)'),
(348322, 1, 0, 255, 'Thiah''s antidote did not do what she hoped. Tried on a hulking helboar, it backfired in a way she still cannot explain, though she prepared it just as she has against spider and snake venoms. She puts it down to one more of Outland''s peculiarities, and has passed the results on to her comrades.', 'quest 10255 description and reward text'),
(348323, 1, 0, 255, 'The crystal is no falling star. Its evil emanations summon the giants and drive them mad, and when Galandria''s circle at its northwest corner healed the land around it, the truth came out: it was dropped on the ridge by the servants of Prince Kael''thas, with Pathaleon the Calculator at work behind it.', 'quest 10351 description and reward text; quest 10349 reward text'),
(348327, 1, 0, 255, 'He did not stay hidden. Legion missives taken from the commanders of the forge camps revealed him as one of Kazzak''s lieutenants and the commander of the Legion''s ground forces in Hellfire Peninsula. Thrall himself has put a price on his head, and the Sons of Lothar count him as evil as any foe they have ever faced.', 'quest 10136 description (one of Kazzak''s lieutenants, commands the ground forces); quest 10399 description (secret Legionlord); quest 10400 description; creature_text 19255 (the warchief''s price on Arazzius''s head)'),
(348327, 2, 0, 255, 'Arazzius fell at last on his own doorstep, among the pools he claimed. Even in death his thoughts were for the one he served, and his final cry was an admission to his master that he had failed.', 'creature_text 19191 group 1 (Master, I have failed...); quest 10136 and 10400 reward text'),
(348328, 1, 0, 255, 'When a young paladin of his people is found slain and blood is shed against the orcs in his name, Amaan offers no judgment. Instead he asks the avenger to look past what the eyes show, and to keep an open mind to every possibility leading to the present and away from it.', 'quest 9430 description (no judgment, see beyond what your eyes show); quest 9545 description (the wise keep an open mind)'),
(348329, 1, 0, 255, 'When a Horde envoy told him that the son of Durotan now rules a free Horde beyond the Dark Portal, untouched by the demons'' taint, Gorkan could hardly believe it, and warned that it had better be no joke. It meant more to his people than words could say. He sent word to Nagrand at once, for Hellscream must hear of it, and a letter to Thrallmar: the Mag''har welcome their kin.', 'quest 9406 description; creature_queststarter 16845 9406 (offered on turning in 9410)'),
(348329, 2, 0, 255, 'In time the warchief''s own envoy came to serve the Mag''har until Thrall''s tribute and diplomats could arrive. It meant much to Gorkan''s people that help came in their time of need, and he swore they will not easily forget the one who came, nor the one who sent them.', 'quest 9441 description and reward text'),
(348330, 1, 0, 255, 'Brought back to him from the ruins at last, battered by the years but whole, the book is the only token Malgor has left of Turalyon. He fights back tears over it: fight beside someone for that many years, he says, and they become closer than family.', 'quest 10058 reward text'),
(348332, 1, 0, 255, 'Each experiment makes the generator stronger. Fed with soul shards torn from the voidwalkers of Void Ridge, it can at last open a rift to the deepest parts of the abyss, and Ogath means to set it off among the void stones on the brink to summon a true prince of the void, Void Baron Galaxis, whose soul shard will tell him what lies beyond.', 'quest 10294 reward text; quest 10295 description'),
(348332, 2, 0, 255, 'Galaxis came through the rift and was destroyed, and his soul shard was carried back to Spinebreaker Post. Others had laughed at Ogath and called him insane for his obsession with the Warp Fields and Void Ridge. Now, he believes, he will unlock the secrets of the voidwalkers and command the power of the abyss itself.', 'quest 10295 reward text'),
(348333, 1, 0, 255, 'The storms slacken once the dreadlords and their imps and infernals are cut down, at least until the Legion brings forth more. Those who survive are sent on to the front lines, to Overlord Hun Maimfist''s crew at Reaver''s Fall or to Field Marshal Rohamus''s at Expedition Point. Both crews are radicals, sworn to the complete extermination of the Burning Legion.', 'quests 10123, 10142 reward text; quests 10124, 10143 descriptions (radicals)'),
(348333, 2, 0, 255, 'There Forward Commanders To''arch and Kingston hand out primers built in Area 52, which turn the demons'' own power into explosives. Set off inside the portals of the Legion Front, they tear the portals apart and stem the flow of reinforcements for a long time.', 'quests 10208, 10144 descriptions and reward text'),
(348333, 3, 0, 255, 'Next come the twin gateways, Murketh and Shaadraz, on either side of the Path of Glory. Recruits are sent aloft on armored wyverns and gryphons to bomb them, setting the Legion back weeks. Then the Horde''s riders are handed bombs for a new target, while the Alliance''s are sent on to Shatter Point, a Wildhammer attack base on a floating piece of land near the portal.', 'quests 10129, 10146 descriptions and reward text; quest 10162 description (offered on turning in 10129); quest 10340 description (offered on turning in 10146; Shatter Point)'),
(348333, 4, 0, 255, 'That target was the Abyssal Shelf, the Legion''s main production grounds behind the forge camps. From the wyverns of Reaver''s Fall and the gryphons of Shatter Point, a floating base that rarely tips, both sides bombed its gan''arg peons, mo''arg overseers and fel cannons from the air, and showed the Legion that not even the skies are safe.', 'quests 10162, 10163 descriptions, log text and request text; quest 10340 reward text, 10344 reward text (Shatter Point)'),
(348334, 1, 0, 255, 'Each side takes a Legion missive from the camps'' commanders, written in a scrawl that seems to twist and burn before the eyes. Magister Bloodhawk in Thrallmar and Warp-Scryer Kryv in Honor Hold decipher them and find the same name: Arazzius the Cruel, a secret Legionlord and one of Kazzak''s lieutenants, who commands the demons of the peninsula and is massing terrorfiends at the Pools of Aggonar.', 'quests 10393, 10395 descriptions (the missives); quest 10136 description; quest 10399 description; item 29590 (Razorsaw) starts 10393; item 29588 (Arix''Amal) starts 10395'),
(348334, 2, 0, 255, 'Thrallmar and Honor Hold both sent their champions to end him, and Arazzius died at the pools. Nazgrel declared that Hellfire belonged to the Horde once again and wished Thrall had been there to see it. Danath praised the Light and looked ahead to the day the Legion runs for home, and the Sons of Lothar can go home too.', 'quest 10136 reward text; quest 10400 reward text'),
(348335, 1, 0, 255, 'For the Alliance, Zeth''Gor gives up a grim find: talismans the Bleeding Hollow make from the insignias of fallen Honor Hold soldiers, cursed to work against the living. Corporal Ironridge at Expedition Point gathers them to honor the dead, then sends recruits after Warlord Morkh, whose clever, cruel tactics have cut deep. Morkh dies in his barracks, and his shattered armor is brought back to hearten the soldiers.', 'quests 10482, 10483, 10484 descriptions and reward text; quest 10485 description and reward text'),
(348335, 2, 0, 255, 'For the Horde, the blood passes from Apothecary Zelana at Reaver''s Fall to Albreck at Spinebreaker Post, who has Bleeding Hollow blood boiled in the clan''s own cursed cauldron to free it of the witches'' curses, and then to Antonivich in Thrallmar. The Royal Apothecary Society means to learn how the orcs of Hellfire became fel orcs, and to keep that tragedy from ever befalling the orcs of the Horde.', 'quests 10449, 10242, 10538 descriptions; quest 10835 description and reward text'),
(348335, 3, 0, 255, 'Antonivich''s demoniac scryer, fed the souls of Shattered Hand orcs, takes its reading of the citadel from Hellfire Basin. Then Nazgrel''s blood burns for battle. Force-Commander Gorax falls at the citadel''s foot, a challenge from the Horde is planted on his corpse, and the Hand of Kargath answers it and dies. The war on the fel orcs, Nazgrel says, is also a battle within the orcs themselves, and one they will win.', 'quests 10864, 10838 descriptions; quest 10875 reward text; quest 10876 description and reward text'),
(348336, 1, 0, 255, 'Then the exorcism begins. The thing inside the colonel mocks the anchorite and swears the soul is its own, and the colonel rises floating from the floor, but Barada''s faith holds and the darkness is cast back where it came from. Freed of the pit of blackness inside him, Jules looks up and sees the face of his savior.', 'quest 10935 description and reward text; creature_text 22431, 22432; npc_text 10706'),
(348336, 2, 0, 255, 'A messenger who had been waiting in the hall seems to have fled at the sight of the floating colonel, and Danath has heard all about it. The Shattered Hand in front of Hellfire Citadel are organizing for an all-out assault, and he sends Jules''s savior to the citadel''s foot to kill the one in charge, Drillmaster Zurok.', 'quest 10936 description and reward text; quest 10937 description'),
(348336, 3, 0, 255, 'Zurok fell at the foot of the citadel, and Danath''s scouts soon reported the Shattered Hand there in disarray without their drillmaster. It had been a long road from Zeth''Gor to the citadel''s gates, and Danath honored the one who walked it with armor from the hold.', 'quest 10937 reward text'),
(348337, 1, 0, 255, 'Nazgrel''s agent found Krun Spinebreaker already dead, struck down from behind by a heavy stone axe of orcish make but of materials like nothing the Horde has seen. Nazgrel could hardly believe it, and wondered aloud whether they had found them at last. Whoever made that axe, he said, knows the old ways, and must be found by something surer than ordinary tracking.', 'quest 9400 reward text; quest 9401 description and reward text; quest 9405 description (offered on turning in 9401)'),
(348337, 2, 0, 255, 'Far Seer Regulkut gave the agent a wolf totem to call a spirit that follows not scent but essence. The ancestral spirit wolf led the way to Mag''har Post, hidden in the hills, where brown orcs untouched by the demons'' blood have survived. Gorkan Bloodfist heard the news of Thrall''s free Horde, sent word to Nagrand, and gave the agent a letter of welcome for Thrallmar.', 'quest 9410 description and reward text; quest 9406 description (offered on turning in 9410)'),
(348337, 3, 0, 255, 'True orcs, here in Hellfire. Nazgrel''s letter, under his personal seal, reached Thrall in Orgrimmar, and the warchief''s jaw slackened as he read. He resolved to reach his people as soon as he could, but matters in Durotar held him, so he sent the bearer back to serve the Mag''har until his tribute and diplomats arrive.', 'quest 9406 reward text; quest 9438 description and reward text; quest 9441 description'),
(348337, 4, 0, 255, 'The first service Earthcaller Ryga asked was drycap, a rare mushroom that grows in Hellfire only in a cave at the Great Fissure, since the post''s orders forbid its orcs to risk being seen gathering it. With it she made a salve, and the grunts sickened by contaminated water were restored. The Mag''har, she said, are in the envoy''s debt.', 'quest 9442 description; quest 9447 description and reward text'),
(348338, 1, 0, 255, 'Sedai lay not far to the east: the body of a young draenei paladin, slain by a blow to his back. The search was over, and the grim news had to be carried home to his brother.', 'quest 9390 reward text; quest 9423 description'),
(348338, 2, 0, 255, 'He had been unarmed. Obadei cursed the cowardly orcs and asked to be left alone with his grief. The Broken Makuru, to whom Sedai was like a brother, demanded vengeance, and sent the newcomer against the Mag''har grunts in the hills for their ancestral beads.', 'quest 9423 reward text; quest 9424 description'),
(348338, 3, 0, 255, 'Afterward, Obadei admitted that such retaliation is not what Sedai would have wanted. Amaan the Wise passed no judgment. He sent the avenger to search the Ruins of Sha''naar for relics, trusting that fate would turn up what they needed, and asked only for patience.', 'quest 9543 description; quest 9430 description'),
(348338, 4, 0, 255, 'With a seer''s relic found there, a vision unfolded at Sedai''s body of how his last moments may have gone. Was the truth what it seemed? No one can know for sure, Amaan says, and whether the old feud with the orcs must go on is still unwritten. What matters is to stay open to the possibilities.', 'quest 9545 description and reward text'),
(348339, 1, 0, 255, 'The disturbances go on regardless. Wesilow wonders whether the ghosts are tied not to the ruins but to their leaders, and sends his helpers against the ghosts of Arch Mage Xintor and Lieutenant Commander Thalvos, who were close to their men. With the officers quieted, he can only hope the foot soldiers will follow.', 'quest 10057 description and reward text'),
(348339, 2, 0, 255, 'Althen found that the tome holds the armory''s whole history, even what came after its fall: the Unyielding have kept their story beyond death. They remain, he learned, as vengeful spirits locked in an endless battle against the fel orc clans, and think only of revenge. So the Horde went after Thalvos''s battle horn, which can summon them.', 'quest 10229 reward text; quest 10230 description and reward text'),
(348339, 3, 0, 255, 'The horn was sounded at an old siege tower east of Spinebreaker Post, where the orc commander Urtrak once captured an Alliance banner. The Unyielding rose to fight beside their summoner and Urtrak died. In the armory''s eastern tower Commander Hogarth offered thanks for honor restored, and a weapon that calls those freed of the curse against their most hated foes.', 'quest 10250 description and reward text; quest 10258 description and reward text'),
(348340, 1, 0, 255, 'The shard goes to Earthbinder Galandria Nightbreeze, who has been waiting for exactly that while Tola''thion dragged his feet. She concludes that the crystal''s evil emanations are summoning the giants and driving them mad. It is too large to move and beyond the Expedition''s power to destroy, so she sends a seed of revitalization to her circle at its edge, to heal the land with rain, growth and returning insects, warning that some outside force is at work.', 'quest 10349 description and reward text; quest 10351 description'),
(348340, 2, 0, 255, 'What comes back are names: Pathaleon the Calculator, and behind him Prince Kael''thas. Galandria is furious. Dropping giant crystals from the sky to ravage the land, she says, is the work of a madman, and she vows the Cenarion Expedition will stop any such attempt again.', 'quest 10351 reward text'),
(348341, 1, 0, 255, 'Naladu is alive, kept by the Illidari for his knowledge of ancient crystals. Wherever a tribe of Broken is enslaved, he says, there is also a traitor who sold his brothers for promises of power, and he sends the stranger to the turncoat''s hut at the top of the stairs for the key to the elders'' chains.', 'quest 10403 reward text; npc_text 9787; quest 10367 description'),
(348341, 2, 0, 255, 'Morod the Windstirrer, Akoru the Firecaller and Aylaan the Waterwaker go free, and the winds, fire and water return to the tribe. Naladu then gives the stranger the Staff of the Dreghood Elders, once a great symbol of their people, to strip Arzeth the Merciless of the powers his dark lord granted him.', 'quest 10368 description and reward text; creature_text 20677, 20678, 20679; quest 10369 description'),
(348341, 3, 0, 255, 'Arzeth dies, and only then does Naladu confess. He was once Naladu the Keeper of Earth, and it was he who betrayed the other elders for empty promises of power. His tribe is free and the spirits have returned, and he can die in peace now, but he will not go with them. He hopes the spirit of earth finds a new servant among his brothers.', 'quest 10369 reward text');
